Optional Chaining Deep:
struct Address {
    let street: String
    let city: String
}

struct Person {
    let name: String
    var address: Address?
    var primaryEmail: String?
    var secondaryEmail: String?
}

let people = [
    Person(name: "Alice", address: Address(street: "123 Main", city: "NYC")),
    Person(name: "Bob", address: nil),
]

for person in people {
    // Chaining: each .? produces optional
    let city = person.address?.city
    print("\(person.name): \(city ?? "unknown location")")

    // Map/filter on optional
    let greeting = person.address.map {
        "\(person.name) lives at \($0.street)"
    }
    print(greeting ?? "No address")

    // Multiple optional binding
    if let email = person.primaryEmail ?? person.secondaryEmail {
        print("Contact: \(email)")
    }

    // flatMap for nested optionals
    let firstChar: Character? = person.primaryEmail?.first
    _ = firstChar
}

